    #[test]
    fn test_key_invalid_primes() {
        let e = RsaPrivateKey::from_components(
            BigUint::from_u64(239).unwrap(),
            BigUint::from_u64(185).unwrap(),
            BigUint::zero(),
            vec![
                BigUint::from_u64(1).unwrap(),
                BigUint::from_u64(239).unwrap(),
            ],
        )
        .unwrap_err();
        assert_eq!(e, Error::InvalidPrime);
    }
